-- Foundation schema shared by both workstreams.
-- Owner after merge: Workstream A. Do not edit this file once it has been applied anywhere;
-- add a new migration instead. See docs/architecture.md#scenelock for the rules encoded here.

create extension if not exists citext;

-- ---------------------------------------------------------------------------
-- Enums
-- ---------------------------------------------------------------------------

create type public.app_role as enum ('user', 'creator', 'moderator', 'admin');

-- Lifecycle shared by every piece of user-generated content (comments, chat, polls, events...).
create type public.content_status as enum ('pending', 'published', 'quarantined', 'removed');

create type public.title_kind as enum ('series', 'movie');

-- ---------------------------------------------------------------------------
-- Profiles
-- ---------------------------------------------------------------------------

create table public.profiles (
  id           uuid primary key references auth.users (id) on delete cascade,
  username     citext not null unique check (username ~ '^[A-Za-z0-9_]{3,30}$'),
  display_name text check (char_length(display_name) <= 60),
  avatar_url   text,
  bio          text check (char_length(bio) <= 500),
  is_private   boolean not null default false,
  role         public.app_role not null default 'user',
  onboarded_at timestamptz,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

-- Every auth user gets a profile with a placeholder username; onboarding replaces it.
create function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.profiles (id, username)
  values (new.id, 'user_' || right(replace(new.id::text, '-', ''), 25));
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

create function public.current_app_role() returns public.app_role
language sql stable security definer set search_path = '' as $$
  select coalesce((select role from public.profiles where id = auth.uid()), 'user'::public.app_role);
$$;

create function public.is_moderator() returns boolean
language sql stable as $$
  select public.current_app_role() in ('moderator', 'admin');
$$;

-- ---------------------------------------------------------------------------
-- Catalog: show -> season -> episode, plus streaming editions (cuts)
-- ---------------------------------------------------------------------------

create table public.shows (
  id          uuid primary key default gen_random_uuid(),
  slug        text not null unique check (slug ~ '^[a-z0-9-]+$'),
  title       text not null,
  kind        public.title_kind not null default 'series',
  description text,
  -- Where the metadata came from (licence / public source). Required by the scope doc.
  source      text not null,
  created_at  timestamptz not null default now()
);

-- An edition is a specific cut/version (e.g. broadcast vs a streamer's cut). Timestamps are only
-- comparable within the same edition.
create table public.editions (
  id         uuid primary key default gen_random_uuid(),
  show_id    uuid not null references public.shows (id) on delete cascade,
  name       text not null,
  is_default boolean not null default false,
  unique (show_id, name)
);
create unique index editions_one_default on public.editions (show_id) where is_default;

create table public.seasons (
  id            uuid primary key default gen_random_uuid(),
  show_id       uuid not null references public.shows (id) on delete cascade,
  season_number int not null,
  title         text,
  unique (show_id, season_number)
);

create table public.episodes (
  id              uuid primary key default gen_random_uuid(),
  show_id         uuid not null references public.shows (id) on delete cascade,
  season_id       uuid references public.seasons (id) on delete set null,
  -- Normalized, show-wide chronological order starting at 1. SceneLock compares this, never
  -- display strings. Specials get their own slot in the order.
  episode_order   int not null check (episode_order >= 1),
  display_code    text not null,              -- e.g. "S2E5", "Reunion Pt 1"
  title           text,                       -- may itself be a spoiler: gate it in the UI/API
  runtime_seconds int check (runtime_seconds > 0),
  air_date        date,
  unique (show_id, episode_order)
);

-- ---------------------------------------------------------------------------
-- Viewer progress
-- ---------------------------------------------------------------------------

-- One row per (user, show). Missing row == "not started". Progress only moves when the user
-- explicitly sets it; never advance it as a side effect of opening a page.
create table public.viewer_progress (
  user_id           uuid not null references public.profiles (id) on delete cascade,
  show_id           uuid not null references public.shows (id) on delete cascade,
  edition_id        uuid references public.editions (id) on delete set null,
  -- Episode the viewer is currently in (or last finished, when episode_completed).
  -- 0 means "not started".
  episode_order     int not null default 0 check (episode_order >= 0),
  -- Position inside episode_order, in seconds of edition_id's timeline.
  position_seconds  int not null default 0 check (position_seconds >= 0),
  episode_completed boolean not null default false,
  updated_at        timestamptz not null default now(),
  primary key (user_id, show_id)
);

-- ---------------------------------------------------------------------------
-- SceneLock
-- ---------------------------------------------------------------------------

-- The single visibility rule. Every content table stores a spoiler boundary
-- (show_id, spoiler_edition_id, spoiler_episode, spoiler_seconds) and its SELECT policy must call
-- this function. A row is visible only if the boundary is at or before the viewer's progress.
--
--   spoiler_episode  = 0      -> show-level content with no episode spoilers.
--   spoiler_seconds  is null  -> spoils the whole episode; requires the episode to be completed.
--   spoiler_seconds  not null -> only comparable in the same edition; otherwise treated as null.
--   any required input null   -> deny.
create function public.scenelock_can_view(
  p_viewer          uuid,
  p_show_id         uuid,
  p_edition_id      uuid,
  p_spoiler_episode int,
  p_spoiler_seconds int
) returns boolean
language plpgsql stable security definer set search_path = '' as $$
declare
  v_progress public.viewer_progress%rowtype;
  v_seconds  int := p_spoiler_seconds;
begin
  if p_show_id is null or p_spoiler_episode is null or p_spoiler_episode < 0 then
    return false;
  end if;

  if p_viewer is not null then
    select * into v_progress
    from public.viewer_progress
    where user_id = p_viewer and show_id = p_show_id;
  end if;

  if not found or p_viewer is null then
    -- Not started / signed out: only show-level, spoiler-free content.
    return p_spoiler_episode = 0;
  end if;

  if p_spoiler_episode = 0 then
    return true;
  end if;

  if v_seconds is not null
     and (p_edition_id is null or p_edition_id is distinct from v_progress.edition_id) then
    v_seconds := null;
  end if;

  if p_spoiler_episode < v_progress.episode_order then
    return true;
  elsif p_spoiler_episode = v_progress.episode_order then
    return v_progress.episode_completed
        or (v_seconds is not null and v_seconds <= v_progress.position_seconds);
  end if;
  return false;
end;
$$;

-- Convenience wrapper for RLS policies: evaluates against the signed-in user.
create function public.scenelock_visible(
  p_show_id uuid, p_edition_id uuid, p_spoiler_episode int, p_spoiler_seconds int
) returns boolean
language sql stable as $$
  select public.scenelock_can_view(auth.uid(), p_show_id, p_edition_id, p_spoiler_episode, p_spoiler_seconds);
$$;

-- ---------------------------------------------------------------------------
-- Blocking (needed by both workstreams from day one)
-- ---------------------------------------------------------------------------

create table public.blocks (
  blocker_id uuid not null references public.profiles (id) on delete cascade,
  blocked_id uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (blocker_id, blocked_id),
  check (blocker_id <> blocked_id)
);

-- True if either user has blocked the other. Use it to hide content and refuse interactions.
create function public.is_blocked_between(a uuid, b uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.blocks
    where (blocker_id = a and blocked_id = b) or (blocker_id = b and blocked_id = a)
  );
$$;

-- ---------------------------------------------------------------------------
-- Audit log (moderation and classification changes)
-- ---------------------------------------------------------------------------

create table public.audit_events (
  id          bigint generated always as identity primary key,
  actor_id    uuid references public.profiles (id) on delete set null,
  action      text not null,          -- e.g. 'content.reclassify', 'content.remove', 'room.ban'
  target_type text not null,          -- e.g. 'comment', 'chat_message', 'poll', 'event', 'profile'
  target_id   text not null,
  reason      text,
  details     jsonb not null default '{}'::jsonb,
  created_at  timestamptz not null default now()
);
create index audit_events_target on public.audit_events (target_type, target_id);

-- ---------------------------------------------------------------------------
-- Row-level security
-- ---------------------------------------------------------------------------

alter table public.profiles        enable row level security;
alter table public.shows           enable row level security;
alter table public.editions        enable row level security;
alter table public.seasons         enable row level security;
alter table public.episodes        enable row level security;
alter table public.viewer_progress enable row level security;
alter table public.blocks          enable row level security;
alter table public.audit_events    enable row level security;

create policy "profiles are readable" on public.profiles
  for select using (true);
-- Users may edit their own profile but never their role (column grant below).
create policy "users update own profile" on public.profiles
  for update using (id = auth.uid()) with check (id = auth.uid());
revoke update on public.profiles from authenticated, anon;
grant update (username, display_name, avatar_url, bio, is_private, onboarded_at, updated_at)
  on public.profiles to authenticated;

-- Catalog is public metadata; writes go through the service role / admin tooling.
-- NOTE: episode titles can be spoilers. The API layer decides whether to return them.
create policy "catalog readable" on public.shows    for select using (true);
create policy "catalog readable" on public.editions for select using (true);
create policy "catalog readable" on public.seasons  for select using (true);
create policy "catalog readable" on public.episodes for select using (true);

create policy "own progress" on public.viewer_progress
  for all using (user_id = auth.uid()) with check (user_id = auth.uid());

create policy "own blocks" on public.blocks
  for all using (blocker_id = auth.uid()) with check (blocker_id = auth.uid());

create policy "moderators read audit" on public.audit_events
  for select using (public.is_moderator());

